-- ES/DE/FR translations for Portugal's remaining deep-dive content:
-- page-level fields (compliance model, footer, 5 section intros),
-- stats, cards (file-format/scope/related), steps, and portal label.
-- INSERT OR IGNORE, safe against existing English rows.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Régimen de software certificado y seguridad documental, con un auténtico mandato de facturación estructurada B2G — sin mandato general B2B/B2C todavía', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El plazo de la QES de 2027 en Portugal ya se ha aplazado una vez a través del proceso anual del Presupuesto del Estado, y lo mismo ocurre con el calendario del archivo SAF-T de contabilidad completa — confirme los requisitos actuales directamente con la Autoridade Tributária antes de construir una integración.', 'El régimen de Portugal es genuinamente inusual entre los países de este seguimiento: todavía no existe un mandato general de facturación electrónica B2B o B2C, pero una densa capa de requisitos de software certificado, seguridad y reporte se aplica a todas las facturas de todos modos — y existe un auténtico mandato de formato estructurado para el suministro al sector público.', 'Portugal ejecuta dos vías genuinamente separadas: un auténtico mandato de formato estructurado para B2G, y un régimen de seguridad y trazabilidad más ligero que se aplica a todo lo demás.', 'Lo más importante que hay que entender sobre Portugal: no existe un paso de compensación, ni un mandato general de transmisión fuera del B2G — la aplicación se basa en cambio en el software certificado y el reporte, no en la validación en tiempo real.', 'El cumplimiento aquí significa trabajar a través de varios requisitos independientes y superpuestos — no un único paso de registro.', 'El modelo de aplicación de Portugal funciona de manera diferente al calendario de sanciones de un país con modelo de compensación — el riesgo real es que una factura se considere inválida directamente, no una sanción graduada por cumplimiento tardío.' FROM countries WHERE name_en = 'Portugal';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Regime für zertifizierte Software und Dokumentensicherheit, mit einer echten strukturierten B2G-Rechnungsvorgabe — noch keine allgemeine B2B/B2C-Vorgabe', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Portugals QES-Frist 2027 hat sich bereits einmal über den jährlichen Staatshaushaltsprozess verschoben, ebenso der Zeitplan für die vollständige Buchführungs-SAF-T-Datei — bestätigen Sie aktuelle Anforderungen direkt bei der Autoridade Tributária, bevor Sie eine Integration aufbauen.', 'Portugals Regime ist unter den Ländern dieses Trackers genuin ungewöhnlich: Es gibt weiterhin keine allgemeine B2B- oder B2C-E-Invoicing-Vorgabe, doch eine dichte Schicht an Anforderungen zu zertifizierter Software, Sicherheit und Meldungen gilt dennoch für jede Rechnung — und für die Belieferung des öffentlichen Sektors besteht eine echte Vorgabe zum strukturierten Format.', 'Portugal fährt zweigleisig, genuin getrennt: eine echte Vorgabe zum strukturierten Format für B2G, und ein leichteres Sicherheits- und Nachverfolgbarkeitsregime, das für alles andere gilt.', 'Das mit Abstand Wichtigste, um Portugal zu verstehen: Es gibt keinen Clearing-Schritt und außerhalb von B2G keine allgemeine Übermittlungsvorgabe — die Durchsetzung stützt sich stattdessen auf zertifizierte Software und Meldungen, nicht auf Echtzeitvalidierung.', 'Compliance bedeutet hier, sich durch mehrere unabhängige, geschichtete Anforderungen zu arbeiten — nicht einen einzigen Registrierungsschritt.', 'Portugals Durchsetzungsmodell funktioniert anders als der Bußgeldkatalog eines Clearing-Modell-Landes — das eigentliche Risiko besteht darin, dass eine Rechnung als von vornherein ungültig behandelt wird, nicht in einer gestuften Sanktion für verspätete Compliance.' FROM countries WHERE name_en = 'Portugal';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Régime de logiciel certifié et de sécurité documentaire, avec une véritable obligation de facturation structurée B2G — pas encore d''obligation générale B2B/B2C', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. L''échéance QES 2027 du Portugal a déjà été reportée une fois via le processus annuel du Budget de l''État, tout comme le calendrier du fichier SAF-T comptable complet — confirmez les exigences actuelles directement auprès de l''Autoridade Tributária avant de construire une intégration.', 'Le régime portugais est véritablement atypique parmi les pays de ce suivi : il n''existe toujours aucune obligation générale de facturation électronique B2B ou B2C, mais une couche dense d''exigences en matière de logiciel certifié, de sécurité et de déclaration s''applique néanmoins à chaque facture — et une véritable obligation de format structuré existe pour l''approvisionnement du secteur public.', 'Le Portugal fonctionne selon deux voies véritablement distinctes : une véritable obligation de format structuré pour le B2G, et un régime de sécurité et de traçabilité plus léger qui s''applique à tout le reste.', 'L''élément le plus important à comprendre sur le Portugal : il n''y a pas d''étape de contrôle, ni d''obligation générale de transmission en dehors du B2G — l''application s''appuie plutôt sur le logiciel certifié et la déclaration, pas sur une validation en temps réel.', 'La conformité ici signifie composer avec plusieurs exigences indépendantes et superposées — pas une simple étape d''enregistrement.', 'Le modèle d''application du Portugal fonctionne différemment du barème de sanctions d''un pays à modèle de contrôle — le risque réel est qu''une facture soit considérée comme invalide d''emblée, et non une sanction graduée pour non-conformité tardive.' FROM countries WHERE name_en = 'Portugal';

