INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato estructurado B2G', '[["Especificación nacional", "CIUS-PT"], ["Basado en", "EN 16931 (norma europea)"], ["Sintaxis", "UBL 2.1 o CEFACT CII"]]', 'CIUS-PT es la adaptación nacional portuguesa de la norma de la UE — las implementaciones deben orientarse específicamente a UBL 2.1 CIUS-PT, no a una construcción genérica de EN 16931.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'B2G structured format';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Strukturiertes B2G-Format', '[["Nationale Spezifikation", "CIUS-PT"], ["Basiert auf", "EN 16931 (europäischer Standard)"], ["Syntaxen", "UBL 2.1 oder CEFACT CII"]]', 'CIUS-PT ist Portugals nationale Anpassung des EU-Standards — Implementierungen sollten speziell auf UBL 2.1 CIUS-PT abzielen, nicht auf einen generischen EN-16931-Aufbau.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'B2G structured format';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format structuré B2G', '[["Spécification nationale", "CIUS-PT"], ["Basé sur", "EN 16931 (norme européenne)"], ["Syntaxes", "UBL 2.1 ou CEFACT CII"]]', 'CIUS-PT est l''adaptation nationale portugaise de la norme européenne — les implémentations doivent cibler spécifiquement UBL 2.1 CIUS-PT, et non une construction EN 16931 générique.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'B2G structured format';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'B2B / B2C — sin mandato estructurado', '[["Formatos aceptados", "Papel, PDF — sin requisito de XML"], ["Lo que se exige de todos modos", "Software certificado por la AT, ATCUD, código QR"]]', 'No confunda "sin mandato de formato estructurado" con "sin requisitos" — la capa de software certificado y seguridad documental se aplica a toda factura independientemente del formato.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'B2B / B2C — no structured mandate';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2B / B2C — keine strukturierte Vorgabe', '[["Akzeptierte Formate", "Papier, PDF — keine XML-Pflicht"], ["Was dennoch gilt", "AT-zertifizierte Software, ATCUD, QR-Code"]]', 'Verwechseln Sie "keine Vorgabe zum strukturierten Format" nicht mit "keine Anforderungen" — die Schicht aus zertifizierter Software und Dokumentensicherheit gilt für jede Rechnung, unabhängig vom Format.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'B2B / B2C — no structured mandate';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'B2B / B2C — aucune obligation structurée', '[["Formats acceptés", "Papier, PDF — aucune exigence XML"], ["Ce qui s''applique quand même", "Logiciel certifié par l''AT, ATCUD, code QR"]]', 'Ne confondez pas « aucune obligation de format structuré » avec « aucune exigence » — la couche logiciel certifié et sécurité documentaire s''applique à chaque facture, quel que soit le format.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'B2B / B2C — no structured mandate';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'La capa QES de 2027', '[["Se aplica a", "Facturas en PDF, B2B y B2C"], ["Requisito del proveedor", "Prestador de servicios de confianza cualificado registrado en la UE"], ["Aplazado desde", "Una fecha original de 2026"]]', 'Esto existe específicamente porque los PDF, a diferencia del XML estructurado, pueden alterarse tras su emisión a menos que estén sellados criptográficamente — la QES es la respuesta de Portugal a esa brecha.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'The 2027 QES layer';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Die QES-Ebene ab 2027', '[["Gilt für", "PDF-Rechnungen, B2B und B2C"], ["Anbieteranforderung", "EU-gelisteter qualifizierter Vertrauensdiensteanbieter"], ["Verschoben von", "Einem ursprünglichen Datum 2026"]]', 'Dies besteht speziell deshalb, weil PDFs, anders als strukturiertes XML, nach der Ausstellung verändert werden können, sofern sie nicht kryptografisch versiegelt sind — QES ist Portugals Antwort auf diese Lücke.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'The 2027 QES layer';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'La couche QES de 2027', '[["S''applique à", "Factures PDF, B2B et B2C"], ["Exigence du prestataire", "Prestataire de services de confiance qualifié inscrit sur liste européenne"], ["Reporté depuis", "Une date initiale de 2026"]]', 'Cela existe spécifiquement parce que les PDF, contrairement au XML structuré, peuvent être modifiés après émission à moins d''être scellés cryptographiquement — la QES est la réponse du Portugal à cette lacune.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'The 2027 QES layer';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Reporte SAF-T (PT)', '[["Archivo mensual de facturación", "Ya obligatorio"], ["Archivo de contabilidad completa", "Obligatorio desde 2028, cubriendo 2027"]]', 'El archivo SAF-T de contabilidad completa tiene un alcance materialmente mayor que el archivo mensual de facturación ya vigente — no asuma que el cumplimiento SAF-T existente lo cubre automáticamente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'SAF-T (PT) reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'SAF-T (PT)-Meldung', '[["Monatliche Abrechnungsdatei", "Bereits erforderlich"], ["Vollständige Buchführungsdatei", "Ab 2028 verpflichtend, für 2027"]]', 'Die vollständige Buchführungs-SAF-T-Datei hat einen materiell größeren Umfang als die bereits geltende monatliche Abrechnungsdatei — gehen Sie nicht davon aus, dass bestehende SAF-T-Konformität dies automatisch abdeckt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'SAF-T (PT) reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Déclaration SAF-T (PT)', '[["Fichier de facturation mensuel", "Déjà exigé"], ["Fichier comptable complet", "Obligatoire à partir de 2028, couvrant 2027"]]', 'Le fichier SAF-T comptable complet a une portée nettement plus large que le fichier de facturation mensuel déjà en vigueur — ne présumez pas que la conformité SAF-T existante le couvre automatiquement.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'file_format' AND dct.title = 'SAF-T (PT) reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Transmisión B2G', '[["Plataforma", "FE-AP (operada por eSPap)"], ["Alternativa", "Otros canales aprobados por la AT"]]', 'Los proveedores de organismos públicos deben conectarse a FE-AP o a un canal equivalente aprobado — este es el único lugar del régimen portugués con un auténtico requisito de transmisión.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'scope_transmission' AND dct.title = 'B2G transmission';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2G-Übermittlung', '[["Plattform", "FE-AP (von eSPap betrieben)"], ["Alternative", "Andere von der AT zugelassene Kanäle"]]', 'Lieferanten öffentlicher Stellen müssen sich mit FE-AP oder einem gleichwertigen zugelassenen Kanal verbinden — dies ist die einzige Stelle in Portugals Regime mit einer echten Übermittlungspflicht.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'scope_transmission' AND dct.title = 'B2G transmission';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Transmission B2G', '[["Plateforme", "FE-AP (exploitée par l''eSPap)"], ["Alternative", "Autres canaux approuvés par l''AT"]]', 'Les fournisseurs d''organismes publics doivent se connecter à FE-AP ou à un canal équivalent approuvé — c''est le seul endroit du régime portugais avec une véritable exigence de transmission.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'scope_transmission' AND dct.title = 'B2G transmission';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Transmisión B2B / B2C', '[["Mandato", "Ninguno — cualquier método de intercambio es legalmente aceptable"], ["Lo que sigue aplicando", "Software certificado, ATCUD, QR y (desde 2027) QES para PDFs"]]', 'Un modelo genuinamente diferente al de los países con modelo de compensación de este seguimiento — no hay ningún paso de validación de la administración tributaria antes de que una factura se emita legalmente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'scope_transmission' AND dct.title = 'B2B / B2C transmission';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2B- / B2C-Übermittlung', '[["Vorgabe", "Keine — jede Austauschmethode ist rechtlich zulässig"], ["Was weiterhin gilt", "Zertifizierte Software, ATCUD, QR und (ab 2027) QES für PDFs"]]', 'Ein genuin anderes Modell als bei Clearing-Modell-Ländern in diesem Tracker — es gibt keinen Validierungsschritt der Steuerbehörde, bevor eine Rechnung rechtsgültig ausgestellt wird.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'scope_transmission' AND dct.title = 'B2B / B2C transmission';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Transmission B2B / B2C', '[["Obligation", "Aucune — tout mode d''échange est légalement acceptable"], ["Ce qui s''applique quand même", "Logiciel certifié, ATCUD, QR et (à partir de 2027) QES pour les PDF"]]', 'Un modèle véritablement différent de celui des pays à modèle de contrôle de ce suivi — il n''y a aucune étape de validation par l''administration fiscale avant qu''une facture ne soit légalement émise.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'scope_transmission' AND dct.title = 'B2B / B2C transmission';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'La red universal: software certificado', '[["Se aplica a", "Toda factura, toda empresa, independientemente del estado B2G"], ["Consecuencia de no usarlo", "La factura es inválida, no simplemente incumplidora"]]', 'Este es el requisito con más probabilidades de sorprender realmente a una empresa — es fácil centrarse en los plazos de B2G/QES y pasar por alto que el software certificado es obligatorio desde 2010-2011.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'scope_transmission' AND dct.title = 'The universal net: certified software';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Das universelle Netz: zertifizierte Software', '[["Gilt für", "Jede Rechnung, jedes Unternehmen, unabhängig vom B2G-Status"], ["Folge der Nichtnutzung", "Rechnung ist ungültig, nicht bloß nicht konform"]]', 'Dies ist die Anforderung, die ein Unternehmen am ehesten tatsächlich überraschen dürfte — es ist leicht, sich auf B2G-/QES-Fristen zu konzentrieren und zu übersehen, dass zertifizierte Software bereits seit 2010–2011 verpflichtend ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'scope_transmission' AND dct.title = 'The universal net: certified software';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Le filet universel : logiciel certifié', '[["S''applique à", "Chaque facture, chaque entreprise, indépendamment du statut B2G"], ["Conséquence de la non-utilisation", "La facture est invalide, pas simplement non conforme"]]', 'Il s''agit de l''exigence la plus susceptible de réellement surprendre une entreprise — il est facile de se concentrer sur les échéances B2G/QES et de négliger le fait que le logiciel certifié est obligatoire depuis 2010-2011.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'scope_transmission' AND dct.title = 'The universal net: certified software';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚠️ El software no certificado invalida la factura, no solo la elección del software', NULL, NULL, 'Una factura emitida con software no certificado por la AT no es una brecha de cumplimiento que corregir más tarde — no se considera en absoluto una factura legalmente válida.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '⚠️ Uncertified software invalidates the invoice, not just the software choice';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚠️ Nicht zertifizierte Software macht die Rechnung ungültig, nicht nur die Softwarewahl', NULL, NULL, 'Eine mit nicht AT-zertifizierter Software ausgestellte Rechnung ist keine später zu behebende Compliance-Lücke — sie gilt überhaupt nicht als rechtsgültige Rechnung.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '⚠️ Uncertified software invalidates the invoice, not just the software choice';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚠️ Un logiciel non certifié invalide la facture, pas seulement le choix du logiciel', NULL, NULL, 'Une facture émise avec un logiciel non certifié par l''AT n''est pas un écart de conformité à corriger plus tard — elle n''est pas du tout considérée comme une facture légalement valable.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '⚠️ Uncertified software invalidates the invoice, not just the software choice';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📋 El incumplimiento B2G es un riesgo separado y distinto', NULL, NULL, 'No emitir facturas estructuradas CIUS-PT a un organismo público es un fallo distinto del requisito general de software certificado, y se evalúa por separado.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '📋 B2G non-compliance is a separate, distinct risk';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📋 B2G-Nichteinhaltung ist ein separates, eigenständiges Risiko', NULL, NULL, 'Das Versäumnis, strukturierte CIUS-PT-Rechnungen an eine öffentliche Stelle auszustellen, ist ein eigenständiger Verstoß, getrennt von der allgemeinen Anforderung zertifizierter Software, und wird separat bewertet.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '📋 B2G non-compliance is a separate, distinct risk';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📋 La non-conformité B2G est un risque distinct et séparé', NULL, NULL, 'Ne pas émettre de factures structurées CIUS-PT à un organisme public constitue un manquement distinct de l''exigence générale de logiciel certifié, et est évalué séparément.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '📋 B2G non-compliance is a separate, distinct risk';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🔄 El plazo de la QES de 2027 ya se aplazó una vez', NULL, NULL, 'Originalmente previsto para 2026, el requisito se trasladó a 2027 mediante el Presupuesto del Estado 2026 — vale la pena seguir de cerca posibles nuevos movimientos en lugar de tratar la fecha actual como segura.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '🔄 The 2027 QES deadline was already deferred once';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🔄 Die QES-Frist 2027 wurde bereits einmal verschoben', NULL, NULL, 'Ursprünglich für 2026 geplant, wurde die Anforderung über den Staatshaushalt 2026 auf 2027 verschoben — es lohnt sich, auf weitere Bewegungen zu achten, statt das aktuelle Datum als sicher zu behandeln.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '🔄 The 2027 QES deadline was already deferred once';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🔄 L''échéance QES de 2027 a déjà été reportée une fois', NULL, NULL, 'Initialement prévue pour 2026, l''exigence a été déplacée à 2027 via le Budget de l''État 2026 — il vaut la peine de surveiller d''éventuels nouveaux changements plutôt que de considérer la date actuelle comme certaine.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '🔄 The 2027 QES deadline was already deferred once';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🗓️ Las dos obligaciones del SAF-T son fáciles de confundir', NULL, NULL, 'El archivo mensual de facturación (ya obligatorio) y el archivo de contabilidad completa (obligatorio desde 2028, cubriendo 2027) son obligaciones genuinamente separadas con alcances distintos.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '🗓️ SAF-T''s two obligations are easy to conflate';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🗓️ Die beiden SAF-T-Pflichten sind leicht zu verwechseln', NULL, NULL, 'Die monatliche Abrechnungsdatei (bereits erforderlich) und die vollständige Buchführungsdatei (ab 2028 fällig, für 2027) sind genuin getrennte Pflichten mit unterschiedlichem Umfang.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '🗓️ SAF-T''s two obligations are easy to conflate';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🗓️ Les deux obligations SAF-T sont faciles à confondre', NULL, NULL, 'Le fichier de facturation mensuel (déjà exigé) et le fichier comptable complet (exigible à partir de 2028, couvrant 2027) sont des obligations véritablement distinctes avec des portées différentes.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Portugal' AND dc.section = 'penalties_related' AND dct.title = '🗓️ SAF-T''s two obligations are easy to conflate';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que su software de facturación está en la lista certificada por la AT', 'Esto se aplica a toda empresa, independientemente de su tamaño o de si se aplica la facturación B2G — usar software no certificado invalida una factura directamente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Confirm your invoicing software is on the AT-certified list';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass Ihre Rechnungssoftware auf der AT-zertifizierten Liste steht', 'Dies gilt für jedes Unternehmen, unabhängig von Größe oder davon, ob B2G-Rechnungsstellung überhaupt zutrifft — die Nutzung nicht zertifizierter Software macht eine Rechnung von vornherein ungültig.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Confirm your invoicing software is on the AT-certified list';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez que votre logiciel de facturation figure sur la liste certifiée par l''AT', 'Cela s''applique à toute entreprise, quelle que soit sa taille ou que la facturation B2G s''applique ou non — l''utilisation d''un logiciel non certifié invalide une facture d''emblée.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Confirm your invoicing software is on the AT-certified list';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si suministra a algún organismo del sector público portugués, configure la emisión CIUS-PT', 'Obligatorio para empresas de cualquier tamaño desde el 1 de enero de 2026 — conéctese a FE-AP o a un canal alternativo aprobado.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'If you supply any Portuguese public-sector body, set up CIUS-PT issuance';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie eine portugiesische öffentliche Stelle beliefern, richten Sie die CIUS-PT-Ausstellung ein', 'Ab dem 1. Januar 2026 für Unternehmen jeder Größe verpflichtend — verbinden Sie sich mit FE-AP oder einem zugelassenen alternativen Kanal.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'If you supply any Portuguese public-sector body, set up CIUS-PT issuance';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous fournissez un organisme public portugais, mettez en place l''émission CIUS-PT', 'Obligatoire pour les entreprises de toute taille à partir du 1er janvier 2026 — connectez-vous à FE-AP ou à un canal alternatif approuvé.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'If you supply any Portuguese public-sector body, set up CIUS-PT issuance';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme la generación de ATCUD y código QR en cada factura', 'Obligatorio desde 2022, independientemente del estado B2G o el formato de la factura — compruebe que esto está realmente automatizado, no aplicado manualmente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Confirm ATCUD and QR code generation on every invoice';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie die ATCUD- und QR-Code-Erzeugung auf jeder Rechnung', 'Seit 2022 erforderlich, unabhängig vom B2G-Status oder Rechnungsformat — prüfen Sie, dass dies tatsächlich automatisiert erfolgt, nicht manuell angewendet wird.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Confirm ATCUD and QR code generation on every invoice';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez la génération de l''ATCUD et du code QR sur chaque facture', 'Exigé depuis 2022, indépendamment du statut B2G ou du format de la facture — vérifiez que cela est réellement automatisé, et non appliqué manuellement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Confirm ATCUD and QR code generation on every invoice';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure el envío mensual del archivo de facturación SAF-T (PT)', 'Ya es un requisito vigente — no lo confunda con el archivo de contabilidad completa, separado y más amplio, exigible desde 2028.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Set up monthly SAF-T (PT) billing file submission';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie die monatliche SAF-T (PT)-Abrechnungsdatei-Einreichung ein', 'Bereits eine geltende Anforderung — verwechseln Sie dies nicht mit der separaten, größeren vollständigen Buchführungs-SAF-T-Datei, die ab 2028 fällig ist.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Set up monthly SAF-T (PT) billing file submission';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place la soumission mensuelle du fichier de facturation SAF-T (PT)', 'Déjà une exigence en vigueur — ne la confondez pas avec le fichier comptable complet, distinct et plus vaste, exigible à partir de 2028.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Set up monthly SAF-T (PT) billing file submission';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Identifique un prestador de servicios de confianza cualificado registrado en la UE para la QES', 'Necesario antes del plazo del 1 de enero de 2027 para las facturas en PDF — es un paso de contratación, no una opción de configuración del software, así que empiece con bastante antelación.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Identify an EU-listed qualified trust service provider for QES';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Identifizieren Sie einen EU-gelisteten qualifizierten Vertrauensdiensteanbieter für QES', 'Vor der Frist am 1. Januar 2027 für PDF-Rechnungen erforderlich — dies ist ein Beschaffungsschritt, keine Softwareeinstellung, also beginnen Sie rechtzeitig im Voraus.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Identify an EU-listed qualified trust service provider for QES';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Identifiez un prestataire de services de confiance qualifié inscrit sur liste européenne pour la QES', 'Nécessaire avant l''échéance du 1er janvier 2027 pour les factures PDF — il s''agit d''une étape d''approvisionnement, pas d''un simple paramètre logiciel, alors commencez bien à l''avance.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Identify an EU-listed qualified trust service provider for QES';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Prepárese para la presentación del SAF-T de contabilidad completa antes de 2028', 'Cubre las transacciones del ejercicio 2027 — un alcance materialmente mayor que el archivo mensual de facturación ya vigente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Prepare for full accounting SAF-T submission by 2028';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bereiten Sie sich auf die vollständige Buchführungs-SAF-T-Einreichung bis 2028 vor', 'Deckt Transaktionen des Geschäftsjahres 2027 ab — ein materiell größerer Umfang als die bereits geltende monatliche Abrechnungsdatei.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Prepare for full accounting SAF-T submission by 2028';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Préparez-vous à la soumission du SAF-T comptable complet d''ici 2028', 'Couvre les transactions de l''exercice 2027 — une portée nettement plus large que le fichier de facturation mensuel déjà en vigueur.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Portugal' AND dst.title = 'Prepare for full accounting SAF-T submission by 2028';

